namespace ghidra.app.plugin.core.assembler;

using docking;
using docking;
using docking.action;
using ghidra.app.context;
using ghidra.app.plugin.core.codebrowser;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.lang;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.util;

public class AssemblePatchAction : DockingAction {
	protected Plugin plugin;

	public AssemblePatchAction(Plugin plugin, string name) : base(name, plugin.getName())
    {
		setPopupMenuData(createMenuData(name));
		setKeyBindingData(new KeyBindingData("ctrl shift J"));
		setHelpLocation(new HelpLocation(plugin.getName(), "assemble_patch"));
		this.plugin = plugin;
	}

	protected MenuData createMenuData(string name) {
		return new MenuData(new string[] { "Assemble..." }, AbstractPatchAction.MENU_GROUP);
	}

	protected bool isApplicableToContext(ActionContext context) {
		if (!(context is ListingActionContext lac)) {
			return false;
		}

		ComponentProvider provider = lac.getComponentProvider();
		if (!(provider is CodeViewerProvider codeViewer)) {
			return false;
		}

		if (codeViewer.isReadOnly()) {
			return false;
		}

		Program program = lac.getProgram();
		if (program == null) {
			return false;
		}

		Address address = lac.getAddress();
		if (address == null) {
			return false;
		}
		MemoryBlock block = program.getMemory().getBlock(address);
		if (block == null || !block.isInitialized()) {
			return false;
		}
		return true;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return base.isEnabledForContext(context) && isApplicableToContext(context);
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return base.isAddToPopup(context) && isApplicableToContext(context);
	}

	protected RegisterValue getInitialContext(Instruction ins, Program program, Address entry) {
		if (ins != null) {
			return ins.getRegisterValue(ins.getBaseContextRegister());
		}
		ProgramContext context = program.getProgramContext();
		return context.getRegisterValue(context.getBaseContextRegister(), entry);
	}

	/**
	 * {@return a dialog for assembly a patch or null if the context is unsuitable}
	 * 
	 * @param ctx the context
	 */
	protected AbstractAssemblePatchDialog<object> newDialog(ListingActionContext ctx) {
		Program program = ctx.getProgram();
		Address entry = ctx.getAddress();
		Instruction ins = program.getListing().getInstructionContaining(entry);
		return new AssemblePatchDialog(plugin.getTool(), ctx.getNavigatable(), program, entry,
			getInitialContext(ins, program, entry));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!(context is ListingActionContext ctx)) {
			return;
		}
		AbstractAssemblePatchDialog<object> dialog = newDialog(ctx);
		if (dialog == null) {
			return;
		}
		plugin.getTool().showDialog(dialog);
	}
}
